import threading
from concurrent.futures import Future

class OncePerKey:
    def __init__(self, compute):
        self._compute = compute
        self._lock = threading.Lock()
        self._futs = {}

    def get(self, key):
        with self._lock:               # short critical section
            fut = self._futs.get(key)
            owner = fut is None
            if owner:
                fut = Future()
                self._futs[key] = fut
        if owner:                      # compute outside the lock
            try:
                fut.set_result(self._compute(key))
            except BaseException as e:
                fut.set_exception(e)
        return fut.result()            # waits if another thread computes
